source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    edge_counts = Counter()
    for c in range(w):
        if grid[0][c] != bg: edge_counts[grid[0][c]] += 1
        if grid[h-1][c] != bg: edge_counts[grid[h-1][c]] += 1
    for r in range(h):
        if grid[r][0] != bg: edge_counts[grid[r][0]] += 1
        if grid[r][w-1] != bg: edge_counts[grid[r][w-1]] += 1
    border = edge_counts.most_common(1)[0][0]

    def runs(vals):
        out=[]; i=0
        while i < len(vals):
            if vals[i] == border:
                j=i
                while j+1 < len(vals) and vals[j+1] == border: j+=1
                out.append((i,j)); i=j+1
            else: i+=1
        return out

    vertical = (runs([grid[r][0] for r in range(h)]), runs([grid[r][w-1] for r in range(h)]))
    horizontal = (runs(grid[0]), runs(grid[h-1]))
    axis = None
    # The task uses a paired equal-length segment on opposite edges.
    for candidate, sides in (("v", vertical), ("h", horizontal)):
        a,b=sides
        if len(a)==1 and len(b)==1 and (a[0][1]-a[0][0] == b[0][1]-b[0][0]):
            axis=candidate; segs=sides; break
    if axis is None:
        return g
    markers=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and grid[r][c] != border:
                markers.append((r,c,grid[r][c]))
    if not markers:
        return g
    paint = markers[0][2]

    for r,c,color in markers:
        if color != paint: continue
        if axis == "v":
            pos = r
        else:
            pos = c
        src_side = None
        src_run = None
        dst_run = None
        for side_idx, run in enumerate(segs):
            if run[0][0] <= pos <= run[0][1]:
                src_side=side_idx; src_run=run[0]; dst_run=segs[1-side_idx][0]
                break
        if src_run is None: continue
        offset = pos-src_run[0]
        mapped = dst_run[0]+offset
        if axis == "v":
            # Paint from the matching border to the marker, then its paired full ray.
            if src_side == 0:
                for cc in range(1,c):
                    if g[r][cc] == bg: g[r][cc]=color
            else:
                for cc in range(w-2,c,-1):
                    if g[r][cc] == bg: g[r][cc]=color
            g[r][c]=4
            dst_side=1-src_side
            edge_col = 0 if dst_side == 0 else w-1
            step = 1 if dst_side == 0 else -1
            cc=edge_col+step
            while 0 <= cc < w:
                if g[mapped][cc] == bg: g[mapped][cc]=color
                cc += step
        else:
            if src_side == 0:
                for rr in range(1,r):
                    if g[rr][c] == bg: g[rr][c]=color
            else:
                for rr in range(h-2,r,-1):
                    if g[rr][c] == bg: g[rr][c]=color
            g[r][c]=4
            dst_side=1-src_side
            edge_row = 0 if dst_side == 0 else h-1
            step = 1 if dst_side == 0 else -1
            rr=edge_row+step
            while 0 <= rr < h:
                if g[rr][mapped] == bg: g[rr][mapped]=color
                rr += step
    return g
